#!/bin/sh
# Rebuild vendor/codemirror.js — the vendored CodeMirror 6 bundle — and vendor/codemirror.LICENSE.txt.
#
#     sh loom/library/file-viewer/vendor/build.sh
#
# To BUMP: edit the exact versions in package.json (no ranges: the lock is the pin), run
# `npm install --package-lock-only` in this folder, then this script, then `deno task build` in the app's own
# folder — which COPIES these two files into `assets/`, and is the only writer of that directory. Needs npm
# and network; nothing is left behind here. Measure the result against MAX_APP_BYTES
# (tests/app_viewer_edit_test.ts does).
set -eu
here=$(cd "$(dirname "$0")" && pwd)
out="$here"
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
cp "$here/package.json" "$here/package-lock.json" "$here/entry.js" "$work/"
cd "$work"
npm ci --no-audit --no-fund --ignore-scripts >/dev/null
# esbuild's own binary arrives as an optional dependency, so --ignore-scripts does not break it.
./node_modules/.bin/esbuild entry.js --bundle --format=esm --minify --legal-comments=none --outfile=out.js
{
  echo "// CodeMirror 6, VENDORED — one pre-built ESM bundle. DO NOT EDIT: generated by"
  echo "//     sh loom/library/file-viewer/vendor/build.sh"
  echo "// from vendor/entry.js with the exact versions in vendor/package-lock.json:"
  node -e 'const l=require("./package-lock.json").packages;for(const[k,v]of Object.entries(l)){if(!k||/esbuild/.test(k))continue;console.log("//   "+k.replace(/^node_modules\//,"")+"@"+v.version)}'
  echo "// MIT licensed; the licences are in codemirror.LICENSE.txt beside this file."
  cat out.js
} > "$out/codemirror.js"
# The licence of EVERY package in the bundle, grouped by identical text.
node -e '
const fs=require("fs"),l=require("./package-lock.json").packages,by=new Map();
for(const[k,v]of Object.entries(l)){if(!k||/esbuild/.test(k))continue;
  const d=k,f=fs.readdirSync(d).find(n=>/^licen[cs]e/i.test(n));
  if(!f)throw new Error(k+": no LICENSE file");
  if(v.license!=="MIT")throw new Error(k+": licence is "+v.license+", not MIT");
  const t=fs.readFileSync(d+"/"+f,"utf8").trim();
  by.set(t,[...(by.get(t)||[]),k.replace(/^node_modules\//,"")+"@"+v.version])}
let o="Licences of the packages bundled into codemirror.js (all MIT).\n";
for(const[t,ps]of by)o+="\n"+"=".repeat(72)+"\n"+ps.join("\n")+"\n\n"+t+"\n";
fs.writeFileSync(process.argv[1],o)' "$out/codemirror.LICENSE.txt"
echo "wrote $(wc -c < "$out/codemirror.js") bytes to vendor/codemirror.js"
